"""Verify documented transport identity and availability; no board semantics."""
from pathlib import Path
import base64,hashlib,json,sys

def discovered(root, manifests):
    result=[]
    def walk(value, name, pointer):
        if isinstance(value,dict):
            if isinstance(value.get('path'),str) and value['path'].startswith(('native/','source/')):
                result.append({'manifest':name,'pointer':pointer,'path':value['path'],'bytes':value.get('bytes',value.get('safe_bytes')),'sha256':value.get('sha256',value.get('safe_sha256'))})
            for key, item in value.items(): walk(item,name,pointer+'/'+key)
        elif isinstance(value,list):
            for i,item in enumerate(value): walk(item,name,pointer+'/'+str(i))
    for name in manifests: walk(json.loads((root/name).read_text()),name,'')
    return result

def validate(root,inventory):
    actual=discovered(root,inventory['manifests'])
    canonical=lambda x:json.dumps(x,sort_keys=True)
    if sorted(map(canonical,actual)) != sorted(map(canonical,inventory['references'])): raise ValueError('Manifest reference inventory differs')
    private=set(inventory['explicit_private_paths']); validated=set()
    for record in actual:
        path=record['path']
        if path in private: continue
        p=root/path
        if not p.is_file(): raise ValueError('Missing published transport: '+path)
        encoded=p.read_bytes()
        # Original manifests declare one terminal LF; do not normalize history.
        if not encoded.endswith(b'\n') or encoded.endswith(b'\n\n'): raise ValueError('Original transport grammar: '+path)
        decoded=base64.b64decode(encoded[:-1],validate=True)
        if base64.b64encode(decoded)+b'\n' != encoded: raise ValueError('Noncanonical transport: '+path)
        if len(decoded)!=record['bytes'] or hashlib.sha256(decoded).hexdigest()!=record['sha256']: raise ValueError('Transport identity mismatch: '+path)
        validated.add(path)
    return {'references':len(actual),'unique_paths':len(set(x['path'] for x in actual)),'published_unique_valid':len(validated),'explicit_private_paths':sorted(private),'scope':'Transport closure of exact named historical manifests, not board or release validation'}

if __name__=='__main__':
    try: print(json.dumps(validate(Path(sys.argv[1]),json.loads(Path(sys.argv[2]).read_text()))))
    except Exception as e: print(type(e).__name__+': '+str(e),file=sys.stderr);sys.exit(1)
